@st.cache_resource(show_spinner=False)
def prepare_game():
    raw = base64.b64decode(_PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != _PAYLOAD_SHA256:
        raise ValueError("app.py의 내장 자료가 손상됐습니다. 파일 전체를 다시 업로드해 주세요.")
    root = Path(tempfile.mkdtemp(prefix="underrune-knight-"))
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        for item in archive.infolist():
            destination = (root / item.filename).resolve()
            if not destination.is_relative_to(root.resolve()):
                raise ValueError("잘못된 게임 자료 경로입니다.")
            if item.is_dir():
                destination.mkdir(parents=True, exist_ok=True)
            else:
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(archive.read(item))
    return components.declare_component("underrune_knight_r2", path=str(root))

def main():
    st.set_page_config(page_title="기사 패턴 · UnderRune", page_icon="⚔️", layout="wide")
    st.caption("기사 패턴 16종 · 갑옷 두 슬롯 · Streamlit 재구성판 r2")
    try:
        with st.spinner("게임을 준비하고 있습니다…"):
            game = prepare_game()
        game(build=_BUILD, key="knight_game", default=None)
    except Exception as exc:
        st.error("게임 준비에 실패했습니다. 아래 오류 내용을 보내주세요.")
        st.exception(exc)

if __name__ == "__main__":
    main()
